"""
Combine every earlier step into the full pipeline and

report the final answer. The final answer is the ionization potential

of one named orbital at the full ADC-G3W2 level of theory.

This step performs no new derivation of its own.

It solves the direct RPA problem, builds the GW effective integrals,

builds the full tier-4 (ADC-G3W2) effective Hamiltonian including the

three-hole-two-particle block, and diagonalizes it. It then identifies

the physically meaningful quasiparticle root. This root is the

eigenvalue whose eigenvector has the largest overlap with the bare

reference orbital. This overlap is called the quasiparticle weight. For

a well-behaved quasiparticle peak, this root is also the eigenvalue

nearest the starting orbital energy.

Returns
-------
a single float, the ADC-G3W2 ionization potential     of the probed orbital, in the same energy units as eps and     chem_spatial.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def adc_g3w2_ionization_potential(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
    probe: int,
) -> float:
    """
    Compute the ionization potential of one active spin-orbital at the
    full ADC-G3W2 level.

    Args:
        eps: orbital energy of each active spin-orbital.
        chem_spatial: bare two-electron Coulomb integrals over the
            active spatial orbitals, as in the earlier steps.
        occ, vir: the occupied and virtual active spin-orbital indices.
        probe: the active spin-orbital index whose ionization potential
            is sought.

    Conventions:
        - The ionization potential is reported as a positive number,
          the energy required to remove the electron. It is the
          negative of the quasiparticle eigenvalue whose eigenvector
          has the largest overlap (squared component) with the bare
          reference orbital. It is not simply the eigenvalue
          numerically closest to the starting orbital energy.

    """
    return 0.0

# =============================================================================
# GOLD SOLUTION
# =============================================================================

def _oracle_adc_g3w2_ionization_potential(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
    probe: int,
) -> float:
    omega, X, Y = _oracle_direct_rpa(eps, chem_spatial, occ, vir)
    M = _oracle_gw_effective_integrals(eps, chem_spatial, occ, vir, omega, X, Y)
    H = _oracle_three_hole_two_particle_augmented_matrix(eps, chem_spatial, occ, vir, omega, M, probe)
    evals, evecs = _oracle_symmetric_eigensystem(H)
    best_i = 0
    best_w = -1.0
    for i in range(len(evals)):
        w = evecs[i][0]*evecs[i][0]
        if w > best_w:
            best_w = w
            best_i = i
    return -evals[best_i]

